(4619895, 666324, 24976, '<td valign="top">i think it needs a bit more highlights in places.</td>', 'i think it needs a bit more highlights in places.', '2008-04-07 01:53:26.000000', NULL, 1),
(4619899, 665223, 46778, '<td valign="top">Nice concept and pic. If the eyes are the focus of the shoot I wish that the would be a little bit more in focus instead of the forehead IMHO. The energy of the child is well captured. -6-</td>', 'Nice concept and pic. If the eyes are the focus of the shoot I wish that the would be a little bit more in focus instead of the forehead IMHO. The energy of the child is well captured. -6-', '2008-04-07 01:54:32.000000', NULL, 1),
