(4621598, 665223, 2134, '<td valign="top">The eyes are nice, however the rest of the photo is not very pleasing...</td>', 'The eyes are nice, however the rest of the photo is not very pleasing...', '2008-04-07 17:33:49.000000', NULL, 1),
(4621616, 666435, 2134, '<td valign="top">Clean and simple... maybe just a little to subtle.</td>', 'Clean and simple... maybe just a little to subtle.', '2008-04-07 17:42:30.000000', NULL, 1),
