(4621932, 666463, 90495, '<td valign="top">It says vote me 5, just like in the picture. ;\</td>', 'It says vote me 5, just like in the picture. ;\', '2008-04-07 21:06:03.000000', NULL, 1),
(4621934, 666435, 90495, '<td valign="top">Oh my this is so soft i''m afraid to breathe in fear it will change.</td>', 'Oh my this is so soft i''m afraid to breathe in fear it will change.', '2008-04-07 21:07:29.000000', NULL, 1),
(4621945, 665416, 90495, '<td valign="top">Hmmm, mmmm, hmmhmm, mmmmmmm.</td>', 'Hmmm, mmmm, hmmhmm, mmmmmmm.', '2008-04-07 21:10:49.000000', NULL, 1),
(4621947, 665799, 36382, '<td valign="top">This is a cool idea.  You have a lot of jagged edges though.  Nothing really to do with the quality of the photograph more to do with how you prepared it for the challenge, I think.</td>', 'This is a cool idea.  You have a lot of jagged edges though.  Nothing really to do with the quality of the photograph more to do with how you prepared it for the challenge, I think.', '2008-04-07 21:12:00.000000', NULL, 1),
(4621951, 664874, 90495, '<td valign="top">Superb rendition of a natural process we can''t avoid. The wood''s grain is so fitting to this idea I''m surprised I don''t see this done more often. Wonderful image.</td>', 'Superb rendition of a natural process we can''t avoid. The wood''s grain is so fitting to this idea I''m surprised I don''t see this done more often. Wonderful image.', '2008-04-07 21:14:14.000000', NULL, 1);
