(4621953, 666426, 90495, '<td valign="top">So courageous I''m speechless.</td>', 'So courageous I''m speechless.', '2008-04-07 21:16:30.000000', NULL, 1),
(4621998, 666359, 67152, '<td valign="top">nice grip - i just wish the w/b were set a bit better - the hands seem too orange</td>', 'nice grip - i just wish the w/b were set a bit better - the hands seem too orange', '2008-04-07 21:26:30.000000', NULL, 1),
(4622062, 666321, 90495, '<td valign="top">ROFL oh man this is neat. So, what plant is this? I can''t wait to read the comments on this one.</td>', 'ROFL oh man this is neat. So, what plant is this? I can''t wait to read the comments on this one.', '2008-04-07 21:37:49.000000', NULL, 1),
(4622096, 666446, 50695, '<td valign="top">I think the composition would have been more effective without the selective desaturation, probably all in b/w.</td>', 'I think the composition would have been more effective without the selective desaturation, probably all in b/w.', '2008-04-07 21:45:49.000000', NULL, 1),
(4622140, 666371, 50695, '<td valign="top">armpit!</td>', 'armpit!', '2008-04-07 21:56:06.000000', NULL, 1),
(4622178, 666405, 58728, '<td valign="top">LOL!  This is great! Made me laugh. Awesome composition too - the tilt adds to the image - IMO.</td>', 'LOL!  This is great! Made me laugh. Awesome composition too - the tilt adds to the image - IMO.', '2008-04-07 22:19:28.000000', NULL, 1),
(4622193, 666002, 51750, '<td valign="top">The way his arms are positioned makes it look like the hands are connected to the biceps, not the forearms. Simply making him hold them lower would''ve fixed this.</td>', 'The way his arms are positioned makes it look like the hands are connected to the biceps, not the forearms. Simply making him hold them lower would''ve fixed this.', '2008-04-07 22:30:06.000000', NULL, 1),
(4622205, 666538, 56658, '<td valign="top">the hand looks strange like you smudged it in post or something that kinda ruins it for me.</td>', 'the hand looks strange like you smudged it in post or something that kinda ruins it for me.', '2008-04-07 22:36:33.000000', NULL, 1),
(4622206, 666494, 56658, '<td valign="top">love the crop. it really adds a dramatic touch for me.</td>', 'love the crop. it really adds a dramatic touch for me.', '2008-04-07 22:37:27.000000', NULL, 1),
(4622209, 666435, 56658, '<td valign="top">love the high key subtleness to this. awesome job.</td>', 'love the high key subtleness to this. awesome job.', '2008-04-07 22:39:32.000000', NULL, 1),
(4622211, 665799, 56658, '<td valign="top">seems noisy or oversharpened but nice idea.</td>', 'seems noisy or oversharpened but nice idea.', '2008-04-07 22:40:20.000000', NULL, 1),
(4622225, 665999, 45475, '<td valign="top">Can''t say I understand the message, but that''s ok. What I can say is I think the light is a bit flat, almost like it lacks contrast but not. Strange. Not sure about the angle either, there''s no drama, no leading lines... it''s kinda just "BAM, here are my fingers wrapped around a gun".</td>', 'Can''t say I understand the message, but that''s ok. What I can say is I think the light is a bit flat, almost like it lacks contrast but not. Strange. Not sure about the angle either, there''s no drama, no leading lines... it''s kinda just "BAM, here are my fingers wrapped around a gun".', '2008-04-07 22:47:49.000000', NULL, 1),
(4622226, 666419, 56658, '<td valign="top">the lines are good but the eye sets this way over the top for me very nice.</td>', 'the lines are good but the eye sets this way over the top for me very nice.', '2008-04-07 22:48:17.000000', NULL, 1),
(4622246, 666420, 33769, '<td valign="top">I like the lighting and effect of shadows, mixed with the message and crossed fingers between the shoulderblades/along the back- well thought out- nice image! :)</td>', 'I like the lighting and effect of shadows, mixed with the message and crossed fingers between the shoulderblades/along the back- well thought out- nice image! :)', '2008-04-07 22:58:24.000000', NULL, 1),
(4622250, 664446, 90414, '<td valign="top">A stunning photo... I think the soft focus eye adds to the drama and mystery.</td>', 'A stunning photo... I think the soft focus eye adds to the drama and mystery.', '2008-04-07 22:59:59.000000', NULL, 1),
(4622252, 666345, 90414, '<td valign="top">Superb shot.</td>', 'Superb shot.', '2008-04-07 23:01:22.000000', NULL, 1),
(4622253, 666399, 10818, '<td valign="top">Amazing textures and lighting.  Quite gritty, great shot.</td>', 'Amazing textures and lighting.  Quite gritty, great shot.', '2008-04-07 23:01:24.000000', NULL, 1),
(4622259, 666122, 56658, '<td valign="top">love his work and this is a pretty good take on it. the paint job isn''t as good but that is not a fair comparison. excellent job.</td>', 'love his work and this is a pretty good take on it. the paint job isn''t as good but that is not a fair comparison. excellent job.', '2008-04-07 23:04:50.000000', NULL, 1),
(4622261, 666098, 10818, '<td valign="top">Fabulous background, hand placement is great.</td>', 'Fabulous background, hand placement is great.', '2008-04-07 23:05:13.000000', NULL, 1),
(4622271, 666439, 10818, '<td valign="top">That is sweet, just an adorable photo.<br/>They grow up so fast.  Just ~poof~ and they are on their own...seems like overnight. Highest marks.</td>', 'That is sweet, just an adorable photo.They grow up so fast.  Just ~poof~ and they are on their own...seems like overnight. Highest marks.', '2008-04-07 23:08:04.000000', NULL, 1),
(4622278, 666049, 10818, '<td valign="top">Super DOF and great lighting.</td>', 'Super DOF and great lighting.', '2008-04-07 23:09:09.000000', NULL, 1),
(4622289, 663991, 90414, '<td valign="top">Somehow doesn''t work for me... but extra credit for creativity.</td>', 'Somehow doesn''t work for me... but extra credit for creativity.', '2008-04-07 23:09:58.000000', NULL, 1),
(4622334, 666515, 90414, '<td valign="top">The title narrows it down... I like the background bokeh.</td>', 'The title narrows it down... I like the background bokeh.', '2008-04-07 23:13:20.000000', NULL, 1),
(4622367, 666246, 90414, '<td valign="top">The frame is a bit overwhelming imo, but an excellent shot nonetheless.</td>', 'The frame is a bit overwhelming imo, but an excellent shot nonetheless.', '2008-04-07 23:19:59.000000', NULL, 1),
(4622386, 666419, 90414, '<td valign="top">Evocative and stunning shot.</td>', 'Evocative and stunning shot.', '2008-04-07 23:22:07.000000', NULL, 1),
(4622394, 666405, 90414, '<td valign="top">Ummmm...... nice sofa???</td>', 'Ummmm...... nice sofa???', '2008-04-07 23:25:12.000000', NULL, 1),
(4622433, 666510, 90414, '<td valign="top">Exquisite shot.</td>', 'Exquisite shot.', '2008-04-07 23:39:14.000000', NULL, 1),
(4622450, 666267, 90414, '<td valign="top">Lighting is a bit flat imo.</td>', 'Lighting is a bit flat imo.', '2008-04-07 23:43:00.000000', NULL, 1),
(4622451, 665284, 7485, '<td valign="top">So the jet-black iris is what the title refers to? Problem is that the photo is strange in so many ways (the super-closeup, green duo-tone, way over-sharpened) that the strange iris no longer stands out.</td>', 'So the jet-black iris is what the title refers to? Problem is that the photo is strange in so many ways (the super-closeup, green duo-tone, way over-sharpened) that the strange iris no longer stands out.', '2008-04-07 23:43:04.000000', NULL, 1),
(4622459, 665231, 7485, '<td valign="top">I like the sculpted light and the pose, but that little bit of pant leg at the top is distracting.</td>', 'I like the sculpted light and the pose, but that little bit of pant leg at the top is distracting.', '2008-04-07 23:44:29.000000', NULL, 1),
(4622461, 666272, 80904, '<td valign="top">Too much yellow. It needs more red. ;)</td>', 'Too much yellow. It needs more red. ;)', '2008-04-07 23:44:42.000000', NULL, 1),
(4622469, 666495, 80904, '<td valign="top">man please cut your nails lol. Other than that great shot.</td>', 'man please cut your nails lol. Other than that great shot.', '2008-04-07 23:45:42.000000', NULL, 1),
(4622475, 666419, 80904, '<td valign="top">I really like this one, not just for the obviour reason, but the composition.</td>', 'I really like this one, not just for the obviour reason, but the composition.', '2008-04-07 23:47:57.000000', NULL, 1),
(4622490, 666371, 80904, '<td valign="top">Its an armpit right?</td>', 'Its an armpit right?', '2008-04-07 23:51:58.000000', NULL, 1),
