(4622494, 666284, 7485, '<td valign="top">Interesting idea and I like the soft glow, but a pose like this calls for either perfect symmetry or a deliberately asymmetric angle.</td>', 'Interesting idea and I like the soft glow, but a pose like this calls for either perfect symmetry or a deliberately asymmetric angle.', '2008-04-07 23:53:17.000000', NULL, 1),
(4622502, 665538, 7485, '<td valign="top">Love the lighting and the super-shallow DOF! And a great model too! I''m not sure I would have left those pin-prick catchlights in her eyes though, they are just too small to look natural.</td>', 'Love the lighting and the super-shallow DOF! And a great model too! I''m not sure I would have left those pin-prick catchlights in her eyes though, they are just too small to look natural.', '2008-04-07 23:56:04.000000', NULL, 1),
(4622506, 666323, 7485, '<td valign="top">Very clever!</td>', 'Very clever!', '2008-04-07 23:56:32.000000', NULL, 1),
(4622512, 666420, 80904, '<td valign="top">I really like this shot, however I wish the hand had more details and it wasnt so much in the shadows. The idea is great though.</td>', 'I really like this shot, however I wish the hand had more details and it wasnt so much in the shadows. The idea is great though.', '2008-04-07 23:58:22.000000', NULL, 1),
(4622518, 666399, 7485, '<td valign="top">I realize you are going for a certain look, but it just looks like way over-done processing to me.</td>', 'I realize you are going for a certain look, but it just looks like way over-done processing to me.', '2008-04-08 00:00:05.000000', NULL, 1),
