(4635210, 666419, 31535, '<td valign="top">Wonderful high key shot. What I really like is darkness of the eye and eyebrow. Turns just another breast shot into a great one.</td>', 'Wonderful high key shot. What I really like is darkness of the eye and eyebrow. Turns just another breast shot into a great one.', '2008-04-12 17:10:31.000000', NULL, 1),
(4635240, 666330, 40819, '<td valign="top">Would have shot with a higher or smaller apeture this would have mad the depth of field larger and kept the feet sharp. Unless you were going for only the Toe Nails in focus. Personally if I were going to shoot a foot with a tattoo I would make sure it was in focus not blured by DOF. Just an opinion, don''t take it personally. :)</td>', 'Would have shot with a higher or smaller apeture this would have mad the depth of field larger and kept the feet sharp. Unless you were going for only the Toe Nails in focus. Personally if I were going to shoot a foot with a tattoo I would make sure it was in focus not blured by DOF. Just an opinion, don''t take it personally. :)', '2008-04-12 17:55:08.000000', NULL, 1),
(4635241, 666486, 40819, '<td valign="top">Nice hands but I would have shot them on a solid background, the embroidery distracts and the hands are too dark in comparison to the background.</td>', 'Nice hands but I would have shot them on a solid background, the embroidery distracts and the hands are too dark in comparison to the background.', '2008-04-12 17:56:25.000000', NULL, 1),
(4635243, 666363, 40819, '<td valign="top">Nothing flattering about this, the shoes don''t match the thong, the sleeve is completely out of context and the chain around the waist is not visible enough to contribute to the structure of the photo.</td>', 'Nothing flattering about this, the shoes don''t match the thong, the sleeve is completely out of context and the chain around the waist is not visible enough to contribute to the structure of the photo.', '2008-04-12 17:58:11.000000', NULL, 1),
(4635245, 666293, 40819, '<td valign="top">Way too much photo shop work on this image. It is unnatural. Get it in the camera next time. Over saturated too.</td>', 'Way too much photo shop work on this image. It is unnatural. Get it in the camera next time. Over saturated too.', '2008-04-12 18:00:39.000000', NULL, 1),
(4635246, 666098, 40819, '<td valign="top">Kind of looks familure, now where have I seen this before? Hmmm... Good job though.</td>', 'Kind of looks familure, now where have I seen this before? Hmmm... Good job though.', '2008-04-12 18:01:38.000000', NULL, 1),
(4635249, 666354, 40819, '<td valign="top">Very Pretty. Next time try no oil and just a fine mist of water. Trust me on that one.</td>', 'Very Pretty. Next time try no oil and just a fine mist of water. Trust me on that one.', '2008-04-12 18:04:36.000000', NULL, 1),
